 static final List<Field>FIELDS=new ArrayList<>();static Map request;static TreeMap<String,NPCDefinition>retained;static List<Object>events;static int logs;
 static{for(Class<?>c:Arrays.asList(Definition.class,NPCDefinition.class))for(Field f:c.getDeclaredFields())if(!Modifier.isStatic(f.getModifiers())&&!f.getName().equals("dropTables")){f.setAccessible(true);FIELDS.add(f);}FIELDS.sort(Comparator.comparing(Field::getName));}
 public static class Failure extends RuntimeException{}
