 public static Integer varbit(int id){events.add(Arrays.asList("varbit",id));if(Boolean.TRUE.equals(request.get("failVarbit")))throw new Failure();return Boolean.TRUE.equals(request.get("missingVarbit"))?null:v(request,"configValue",0);}
 public static int varp(int id){events.add(Arrays.asList("varp",id));if(Boolean.TRUE.equals(request.get("failVarp")))throw new Failure();return v(request,"configValue",0);}
 static Field field(String name){return FIELDS.stream().filter(f->f.getName().equals(name)).findFirst().orElseThrow();}
 static Object get(Field f,Object h){try{return f.get(h);}catch(Exception e){throw new RuntimeException(e);}}
 static Object scalar(Object x){return x instanceof Long?((Long)x).intValue():x;}
 static Object convert(Object x,Class<?>t){if(x==null)return null;if(t.isArray()){List l=(List)x;Object a=Array.newInstance(t.getComponentType(),l.size());for(int i=0;i<l.size();i++)Array.set(a,i,convert(l.get(i),t.getComponentType()));return a;}if(t==int.class)return n(x);if(t==short.class)return((Number)x).shortValue();if(t==byte.class)return((Number)x).byteValue();if(x instanceof Map){Map<String,Object>m=new HashMap<>();((Map<String,Object>)x).forEach((k,v)->m.put(k,scalar(v)));return m;}return scalar(x);}
 static Object json(Object x){if(x instanceof Double&&!Double.isFinite((Double)x))return map("$double",String.format("%016x",Double.doubleToRawLongBits((Double)x)));if(x==null||x instanceof String||x instanceof Number||x instanceof Boolean)return x;if(x.getClass().isArray()){List<Object>a=new ArrayList<>();for(int i=0;i<Array.getLength(x);i++)a.add(json(Array.get(x,i)));return a;}if(x instanceof core.game.node.entity.combat.CombatStyle)return map("$combatStyle",((Enum)x).name());if(x instanceof content.global.activity.ttrail.ClueLevel)return map("$clueLevel",((Enum)x).name());if(x instanceof core.game.world.update.flag.context.Graphics){core.game.world.update.flag.context.Graphics g=(core.game.world.update.flag.context.Graphics)x;return map("id",g.getId(),"height",g.getHeight(),"delay",g.getDelay());}if(x instanceof core.game.world.update.flag.context.Animation){core.game.world.update.flag.context.Animation a=(core.game.world.update.flag.context.Animation)x;return map("$animation",map("id",a.getId(),"delay",a.getDelay(),"priority",a.getPriority().name()));}if(x instanceof Map){Map<String,Object>m=new TreeMap<>();((Map<?,?>)x).forEach((k,v)->m.put(k.toString(),json(v)));return m;}throw new AssertionError(x.getClass());}
 static Map<String,Object>snapshot(NPCDefinition h){if(h==null)return null;Map<String,Object>m=new TreeMap<>();for(Field f:FIELDS)m.put(f.getName(),json(get(f,h)));return m;}
 static Object refs(NPCDefinition h,IdentityHashMap<Object,Integer>ids){if(h==null)return null;Map<String,Object>m=new TreeMap<>();m.put("self",ids.computeIfAbsent(h,k->ids.size()));for(Field f:FIELDS)if(f.getType().isArray()||f.getName().equals("handlers")){Object a=get(f,h);m.put(f.getName(),a==null?null:ids.computeIfAbsent(a,k->ids.size()));}return m;}
 public static Object state(){Map<String,Object>defs=new TreeMap<>(),identities=new TreeMap<>(),rs=new TreeMap<>(),ri=new TreeMap<>();IdentityHashMap<Object,Integer>ids=new IdentityHashMap<>();List<Integer>keys=new ArrayList<>(NPCDefinition.getDefinitions().keySet());Collections.sort(keys);for(int k:keys){NPCDefinition h=NPCDefinition.getDefinitions().get(k);defs.put(""+k,snapshot(h));identities.put(""+k,refs(h,ids));}for(String k:retained.keySet()){rs.put(k,snapshot(retained.get(k)));ri.put(k,refs(retained.get(k),ids));}return map("definitions",defs,"identities",identities,"size",keys.size(),"retained",rs,"retainedIdentities",ri,"reader",parser.getReader()!=null);}
 static void set(NPCDefinition h,String name,Object value)throws Exception{Field f=field(name);if(name.equals("handlers")){Map m=(Map)f.get(h);m.clear();((Map<String,Object>)value).forEach((k,v)->m.put(k,scalar(v)));}else f.set(h,convert(value,f.getType()));}
 static NPCDefinition make(Map<String,Object>m)throws Exception{NPCDefinition h=new NPCDefinition(0);for(String k:m.keySet())set(h,k,m.get(k));return h;}
 static NPCDefinition target(Map a){return a.containsKey("ref")?retained.get(a.get("ref")):NPCDefinition.forId(v(a,"slot",0));}
 public static byte[]bytes(String s){byte[]b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
 static Object action(Map a)throws Throwable{String op=(String)a.get("op");switch(op){
 case"load":{Cache.files.clear();Map<String,String>files=(Map)a.get("files");files.forEach((k,v)->Cache.files.put(Integer.parseInt(k),bytes(v)));Cache.failFile=a.containsKey("failFile")?n(a.get("failFile")):null;return null;} case"preload":{for(int i=0;i<v(a,"count",0);i++)NPCDefinition.forId(i);return null;} case"lookup":return snapshot(NPCDefinition.forId(n(a.get("id"))));
 case"config":{java.nio.file.Files.writeString(configDir.resolve("npc_configs.json"),a.containsKey("text")?(String)a.get("text"):pinnedConfig);parser.load();return null;}
 case"put":NPCDefinition.getDefinitions().put(n(a.get("slot")),make((Map)a.get("fields")));return null;
 case"parse":{Method m=NPCDefinition.class.getDeclaredMethod("parse",ByteBuffer.class);m.setAccessible(true);m.invoke(target(a),ByteBuffer.wrap(bytes((String)a.get("data"))));return null;}
 case"retain":retained.put((String)a.get("name"),target(a));return null;
 case"alias":NPCDefinition.getDefinitions().put(n(a.get("to")),target(a));return null;
 case"set":{Map<String,Object>m=(Map)a.get("fields");for(String k:m.keySet())set(target(a),k,m.get(k));return null;}
 case"share":{Field f=field((String)a.get("field"));f.set(NPCDefinition.forId(n(a.get("to"))),f.get(target(a)));return null;}
 case"array":{Object ar=field((String)a.get("field")).get(target(a));int index=n(a.get("index"));Array.set(ar,index,convert(a.get("value"),ar.getClass().getComponentType()));return null;}
 case"animation":return json(target(a).getCombatAnimation(v(a,"index",0)));
 case"graphics":{NPCDefinition h=target(a);h.initCombatGraphics(a.containsKey("values")?(Map)convert(a.get("values"),Map.class):h.getHandlers());return null;}
 case"hasOptions":return target(a).hasOptions(Boolean.TRUE.equals(a.get("examine")));
 case"hasAttack":return target(a).hasAttackOption();case"hasAction":return target(a).hasAction((String)a.get("value"));
 case"child":{NPCDefinition h=target(a).getChildNPC(Boolean.TRUE.equals(a.get("player"))?new core.game.node.entity.player.Player():null);if(a.containsKey("name"))retained.put((String)a.get("name"),h);return snapshot(h);}
 
 default:throw new IllegalArgumentException(op);}}
 static String error(Throwable e){while(e instanceof InvocationTargetException)e=((InvocationTargetException)e).getCause();return e instanceof Failure?"Binding":e.getClass().getSimpleName();}
 public static Object evaluate(Map input)throws Exception{request=input;parser=new core.game.system.config.NPCConfigParser();logs=0;retained=new TreeMap<>();events=new ArrayList<>();NPCDefinition.getDefinitions().clear();Cache.files.clear();Cache.failFile=null;
 if(input.get("kind").equals("decode")){ByteBuffer r=ByteBuffer.wrap(bytes((String)input.get("data")));NPCDefinition h=new NPCDefinition(v(input,"id",0));String error=null;try{Method m=NPCDefinition.class.getDeclaredMethod("parse",ByteBuffer.class);m.setAccessible(true);m.invoke(h,r);}catch(Throwable e){error=error(e);}return map("definition",snapshot(h),"state",state(),"position",r.position(),"error",error,"events",new ArrayList<>(events));}
 for(Object r:(List)input.getOrDefault("initial",new ArrayList<>())){Map row=(Map)r;NPCDefinition.getDefinitions().put(n(row.get("slot")),make((Map)row.get("fields")));}
 List<Object>out=new ArrayList<>();for(Object a:(List)input.get("actions")){events.clear();Object result=null;String error=null;try{result=action((Map)a);}catch(Throwable e){error=error(e);}out.add(map("result",result,"error",error,"state",state(),"events",new ArrayList<>(events)));}return out;}
 public static void main(String[]args)throws Exception{configDir=java.nio.file.Paths.get(args[0]);java.nio.file.Files.createDirectories(configDir);core.ServerConstants.CONFIG_PATH=configDir.toString()+java.io.File.separator;pinnedConfig=java.nio.file.Files.readString(java.nio.file.Paths.get(args[1]));try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8));BufferedWriter w=new BufferedWriter(new OutputStreamWriter(System.out,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){JSONObject c=(JSONObject)new JSONParser().parse(line);c.put("expected",evaluate(c));JSONValue.writeJSONString(c,w);w.newLine();w.flush();}}}
